// Rotate a CCW polygon so it starts at the vertex nearest `target`.
// After clipping Gi by F the result starts at a Gi vertex; the stab loop
// emits new_S.front(), so we aim that vertex at the candidate apex (not
// F[0], which is a bbox corner whenever S is still a single point).
inline void rotate_nearest_xy(std::vector<std::array<double, 2>>& poly,
                              const std::array<double, 2>& target) {
    const int n = static_cast<int>(poly.size());
    if (n < 2) return;
    int best = 0;
    double best_d = std::numeric_limits<double>::infinity();
    for (int i = 0; i < n; ++i) {
        const double dx = poly[i][0] - target[0];
        const double dy = poly[i][1] - target[1];
        const double d = dx * dx + dy * dy;
        if (d < best_d) {
            best_d = d;
            best = i;
        }
    }
    if (best != 0)
        std::rotate(poly.begin(), poly.begin() + best, poly.end());
}

// intersect_prepared with both F and the result already in doubles, so the
// stab loop can keep S as CCW xy and skip the Point round-trip through clip.
//
// When Gi has more vertices than F, clip Gi by F (fewer Sutherland-Hodgman
// passes).  `front_target` (the candidate apex) then becomes new_S.front()
// so the emitted endpoint is independent of clip orientation.  Otherwise
// clip F by Gi, matching the historical subject/clip order.
inline bool intersect_prepared_xy(const std::vector<std::array<double, 2>>& F_in,
                                  const std::vector<std::array<double, 2>>& Gi_xy,
                                  std::vector<std::array<double, 2>>& result,
                                  const std::array<double, 2>* front_target = nullptr) {
    thread_local std::vector<std::array<double, 2>> F_verts;
    dedup_xy_into(F_in, F_verts);
    if (F_verts.size() < 3 || Gi_xy.size() < 3) {
        result.clear();
        return false;
    }
    sh_double::ClipWorkspace& ws = sh_double::get_clip_workspace();
    sh_double::to_ccw(F_verts);
    const bool clip_gi_by_f = Gi_xy.size() > F_verts.size();
    if (clip_gi_by_f) {
        ws.subj = Gi_xy;
        sh_double::clip_convex_ccw(ws.subj, F_verts, ws.out, ws.in);
    } else {
        sh_double::clip_convex_ccw(F_verts, Gi_xy, ws.out, ws.in);
    }
    dedup_xy_into(ws.out, result);
    if (result.size() < 3) {
        result.clear();
        return false;
    }
    if (clip_gi_by_f && front_target)
        rotate_nearest_xy(result, *front_target);
    return true;
}
